"""`LLMProvider` protocol, result shape, and the seam's error taxonomy (ADR 0042).

Error types are the contract: callers branch on TYPE, never message (the ADR 0039
lesson) — "not configured", "provider outage", and "bad output" are three
different states and none may be folded into another.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from typing import Any, Protocol, runtime_checkable

import jsonschema

from backend.app.core.errors import DataQError

LLM_PROVIDERS = ("anthropic", "openai_compatible")
STRUCTURED_OUTPUT_MODES = ("native", "prompt_json")

DEFAULT_TIMEOUT_SECONDS = 120.0
DEFAULT_MAX_TOKENS = 4096


class LLMNotConfiguredError(DataQError):
    status_code = 409
    code = "llm_not_configured"


class LLMProviderError(DataQError):
    """The provider answered with a non-transport failure (auth, bad model, 4xx)."""

    status_code = 502
    code = "llm_provider_error"


class LLMUnavailableError(DataQError):
    """Transport-level outage (unreachable, timeout, 5xx) — never a config state."""

    status_code = 502
    code = "llm_provider_unavailable"


class LLMOutputInvalidError(DataQError):
    """The model's output failed schema validation after the repair round."""

    status_code = 502
    code = "llm_output_invalid"


@dataclass(frozen=True)
class LLMResult:
    text: str
    input_tokens: int | None = None
    output_tokens: int | None = None
    parsed: dict[str, Any] | None = None
    raw: dict[str, Any] = field(default_factory=dict, repr=False)


@runtime_checkable
class LLMProvider(Protocol):
    model: str

    def complete(
        self,
        prompt: str,
        *,
        system: str | None = None,
        max_tokens: int = DEFAULT_MAX_TOKENS,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
    ) -> LLMResult: ...

    def complete_structured(
        self,
        prompt: str,
        *,
        schema: dict[str, Any],
        system: str | None = None,
        max_tokens: int = DEFAULT_MAX_TOKENS,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
    ) -> LLMResult: ...


_FENCE_RE = re.compile(r"```(?:json)?\s*(.*?)```", re.DOTALL)


def extract_json_object(text: str) -> dict[str, Any]:
    """Parse the first JSON object out of model text (bare, fenced, or embedded)."""
    candidates = [text.strip()]
    candidates += [m.strip() for m in _FENCE_RE.findall(text)]
    brace = text.find("{")
    if brace != -1:
        candidates.append(text[brace : text.rfind("}") + 1])
    for candidate in candidates:
        if not candidate:
            continue
        try:
            parsed = json.loads(candidate)
        except (json.JSONDecodeError, RecursionError):
            continue
        if isinstance(parsed, dict):
            return parsed
    raise LLMOutputInvalidError("model output contained no parseable JSON object")


def validate_against_schema(parsed: dict[str, Any], schema: dict[str, Any]) -> None:
    try:
        jsonschema.validate(parsed, schema)
    except jsonschema.ValidationError as exc:
        raise LLMOutputInvalidError(
            f"model output failed schema validation: {exc.message}"
        ) from exc


def prompt_json_instructions(schema: dict[str, Any]) -> str:
    return (
        "Respond with a single JSON object and nothing else — no prose, no code fences. "
        "It must conform exactly to this JSON schema:\n" + json.dumps(schema, sort_keys=True)
    )


def repair_prompt(schema: dict[str, Any], error: str) -> str:
    return (
        f"Your previous response was not valid against the schema ({error}). "
        "Respond again with ONLY the corrected JSON object.\n"
        + prompt_json_instructions(schema)
    )

"""OpenAI-compatible chat-completions provider — Azure OpenAI, Bedrock, and any
local server (Ollama / vLLM / TGI). Deliberately raw `httpx`, no vendor SDK
(ADR 0042): the wire format is three fields and the SDK would be the lock-in.
"""

from __future__ import annotations

from typing import Any

import httpx

from backend.app.llm import base
from backend.app.llm.base import (
    DEFAULT_MAX_TOKENS,
    DEFAULT_TIMEOUT_SECONDS,
    LLMOutputInvalidError,
    LLMProviderError,
    LLMResult,
    LLMUnavailableError,
)

_CONNECT_TIMEOUT_SECONDS = 10.0


class OpenAICompatProvider:
    def __init__(
        self,
        *,
        base_url: str,
        model: str,
        api_key: str | None = None,
        structured_output: str = "native",
        client: httpx.Client | None = None,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.model = model
        self._api_key = api_key
        self._structured_output = structured_output
        self._client = client

    def _headers(self) -> dict[str, str]:
        headers = {"Content-Type": "application/json"}
        if self._api_key:
            headers["Authorization"] = f"Bearer {self._api_key}"
            # Azure OpenAI ignores Authorization and reads api-key; sending both is harmless
            # to every other server and spares a per-vendor auth knob.
            headers["api-key"] = self._api_key
        return headers

    def _post(self, payload: dict[str, Any], timeout: float) -> dict[str, Any]:
        url = f"{self.base_url}/chat/completions"
        timeouts = httpx.Timeout(timeout, connect=_CONNECT_TIMEOUT_SECONDS)
        try:
            if self._client is not None:
                response = self._client.post(
                    url, json=payload, headers=self._headers(), timeout=timeouts
                )
            else:
                with httpx.Client(timeout=timeouts) as client:
                    response = client.post(url, json=payload, headers=self._headers())
        except httpx.HTTPError as exc:
            raise LLMUnavailableError(f"LLM endpoint unreachable: {exc.__class__.__name__}") from exc
        if response.status_code >= 500:
            raise LLMUnavailableError(f"LLM endpoint returned {response.status_code}")
        if response.status_code >= 400:
            raise LLMProviderError(f"LLM endpoint refused the request ({response.status_code})")
        try:
            data = response.json()
        except ValueError as exc:
            raise LLMProviderError("LLM endpoint returned non-JSON") from exc
        if not isinstance(data, dict):
            raise LLMProviderError("LLM endpoint returned a non-object body")
        return data

    def _result(self, data: dict[str, Any]) -> LLMResult:
        try:
            text = data["choices"][0]["message"]["content"] or ""
        except (KeyError, IndexError, TypeError) as exc:
            raise LLMProviderError("LLM response missing choices[0].message.content") from exc
        usage = data.get("usage") or {}
        return LLMResult(
            text=text,
            input_tokens=usage.get("prompt_tokens"),
            output_tokens=usage.get("completion_tokens"),
            raw=data,
        )

    @staticmethod
    def _messages(prompt: str, system: str | None) -> list[dict[str, str]]:
        messages = []
        if system:
            messages.append({"role": "system", "content": system})
        messages.append({"role": "user", "content": prompt})
        return messages

    def complete(
        self,
        prompt: str,
        *,
        system: str | None = None,
        max_tokens: int = DEFAULT_MAX_TOKENS,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
    ) -> LLMResult:
        payload = {
            "model": self.model,
            "max_tokens": max_tokens,
            "messages": self._messages(prompt, system),
        }
        return self._result(self._post(payload, timeout))

    def complete_structured(
        self,
        prompt: str,
        *,
        schema: dict[str, Any],
        system: str | None = None,
        max_tokens: int = DEFAULT_MAX_TOKENS,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
    ) -> LLMResult:
        if self._structured_output == "native":
            payload = {
                "model": self.model,
                "max_tokens": max_tokens,
                "messages": self._messages(prompt, system),
                "response_format": {
                    "type": "json_schema",
                    "json_schema": {"name": "result", "schema": schema, "strict": True},
                },
            }
            result = self._result(self._post(payload, timeout))
            parsed = base.extract_json_object(result.text)
            base.validate_against_schema(parsed, schema)
            return LLMResult(
                text=result.text,
                input_tokens=result.input_tokens,
                output_tokens=result.output_tokens,
                parsed=parsed,
                raw=result.raw,
            )
        return self._prompt_json(
            prompt, schema=schema, system=system, max_tokens=max_tokens, timeout=timeout
        )

    def _prompt_json(
        self,
        prompt: str,
        *,
        schema: dict[str, Any],
        system: str | None,
        max_tokens: int,
        timeout: float,
    ) -> LLMResult:
        first = self.complete(
            f"{prompt}\n\n{base.prompt_json_instructions(schema)}",
            system=system,
            max_tokens=max_tokens,
            timeout=timeout,
        )
        try:
            parsed = base.extract_json_object(first.text)
            base.validate_against_schema(parsed, schema)
        except LLMOutputInvalidError as exc:
            second = self.complete(
                base.repair_prompt(schema, str(exc)),
                system=system,
                max_tokens=max_tokens,
                timeout=timeout,
            )
            parsed = base.extract_json_object(second.text)
            base.validate_against_schema(parsed, schema)
            return LLMResult(
                text=second.text,
                input_tokens=second.input_tokens,
                output_tokens=second.output_tokens,
                parsed=parsed,
                raw=second.raw,
            )
        return LLMResult(
            text=first.text,
            input_tokens=first.input_tokens,
            output_tokens=first.output_tokens,
            parsed=parsed,
            raw=first.raw,
        )

"""Anthropic Messages provider via the official SDK (ADR 0042).

Structured output uses forced tool-choice — one synthetic tool whose
`input_schema` IS the caller's schema — which works uniformly across Claude
model generations, unlike the newer response-format surface.
"""

from __future__ import annotations

from typing import Any

import anthropic

from backend.app.llm import base
from backend.app.llm.base import (
    DEFAULT_MAX_TOKENS,
    DEFAULT_TIMEOUT_SECONDS,
    LLMOutputInvalidError,
    LLMProviderError,
    LLMResult,
    LLMUnavailableError,
)

_STRUCTURED_TOOL_NAME = "emit_result"


class AnthropicProvider:
    def __init__(
        self,
        *,
        model: str,
        api_key: str,
        base_url: str | None = None,
        client: anthropic.Anthropic | None = None,
    ) -> None:
        self.model = model
        self._client = client or anthropic.Anthropic(
            api_key=api_key, base_url=base_url, max_retries=1
        )

    def _create(self, timeout: float, **kwargs: Any) -> anthropic.types.Message:
        try:
            return self._client.with_options(timeout=timeout).messages.create(**kwargs)
        except anthropic.APIConnectionError as exc:  # includes APITimeoutError
            raise LLMUnavailableError(f"Anthropic API unreachable: {exc.__class__.__name__}") from exc
        except anthropic.APIStatusError as exc:
            if exc.status_code >= 500 or exc.status_code == 429:
                raise LLMUnavailableError(f"Anthropic API returned {exc.status_code}") from exc
            raise LLMProviderError(f"Anthropic API refused the request ({exc.status_code})") from exc

    @staticmethod
    def _usage(message: anthropic.types.Message) -> tuple[int | None, int | None]:
        usage = getattr(message, "usage", None)
        if usage is None:
            return None, None
        return getattr(usage, "input_tokens", None), getattr(usage, "output_tokens", None)

    def complete(
        self,
        prompt: str,
        *,
        system: str | None = None,
        max_tokens: int = DEFAULT_MAX_TOKENS,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
    ) -> LLMResult:
        kwargs: dict[str, Any] = {
            "model": self.model,
            "max_tokens": max_tokens,
            "messages": [{"role": "user", "content": prompt}],
        }
        if system:
            kwargs["system"] = system
        message = self._create(timeout, **kwargs)
        text = "".join(block.text for block in message.content if block.type == "text")
        input_tokens, output_tokens = self._usage(message)
        return LLMResult(text=text, input_tokens=input_tokens, output_tokens=output_tokens)

    def complete_structured(
        self,
        prompt: str,
        *,
        schema: dict[str, Any],
        system: str | None = None,
        max_tokens: int = DEFAULT_MAX_TOKENS,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
    ) -> LLMResult:
        kwargs: dict[str, Any] = {
            "model": self.model,
            "max_tokens": max_tokens,
            "messages": [{"role": "user", "content": prompt}],
            "tools": [
                {
                    "name": _STRUCTURED_TOOL_NAME,
                    "description": "Emit the final structured result.",
                    "input_schema": schema,
                }
            ],
            "tool_choice": {"type": "tool", "name": _STRUCTURED_TOOL_NAME},
        }
        if system:
            kwargs["system"] = system
        message = self._create(timeout, **kwargs)
        parsed: dict[str, Any] | None = None
        for block in message.content:
            if block.type == "tool_use" and block.name == _STRUCTURED_TOOL_NAME:
                if isinstance(block.input, dict):
                    parsed = block.input
                break
        if parsed is None:
            raise LLMOutputInvalidError("model returned no structured tool output")
        base.validate_against_schema(parsed, schema)
        input_tokens, output_tokens = self._usage(message)
        return LLMResult(
            text="", input_tokens=input_tokens, output_tokens=output_tokens, parsed=parsed
        )

