    )
    lines = [f"- {name}" for name in columns]
    request = None
    return "Columns:\n" + "\n".join(lines) if lines else "Columns: (could not be listed)"


def _profile_context(suite: Suite, connection: Connection, columns_wanted: bool) -> str:
    if not columns_wanted:
        return ""
    target = suite.target or {}
    secret_store = get_secret_store()
    try:
        columns = profile_service.list_columns(
            connection,
            table=target.get("table"),
            schema=target.get("schema"),
            catalog=target.get("catalog"),
            namespace=target.get("namespace"),
